package com.adnanalhasani.commercial

internal data class ReportCatalogItem(val title: String, val category: String, val source: String, val supported: Boolean, val note: String)

internal fun buildReportsCatalog(cloudMode: Boolean): List<ReportCatalogItem> = listOf(
            ReportCatalogItem("لوحة المؤشرات", "لوحة المعلومات", if (cloudMode) "مبيعات السحابة المحملة" else "المبيعات والمصروفات المحلية", true, "مؤشرات تشغيلية وليست قوائم مالية معتمدة."),
